CREATE Proc [dbo].[ReportTopFivePurchasedReport]@From as datetime,@To as Datetime,@Login as nvarchar(max) as Declare @ReportName as nvarchar(max);set @ReportName='Top Five Purchased Item';select top (5) idc.Qty as PurchaseQty,  CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To], @Login as LoginUser,s.Store,c.Category,sc.Subcategory,i.Item,i.ItemId,U.Unit as PackingType,@ReportName as ReportName,iu.PkFactor as UnitQty,Cast(isnull(Round([dbo].uspGetItemAvgRateFunc(s.SId,i.ItemId,@From,@To,1),2),0) AS DECIMAL (18,2)) as Rate,(Select Distinct(Unit) from unit  where UId=idc.Unit) as UnitType,ipl.ParLevel from InvoiceMaster_CompanyNew im  inner join InvoiceDetail_CompanyNew idc on im.InvoiceId=idc.InvoiceId inner join Vendor v on v.VId=im.VId inner join Store s on im.SId=s.SId inner join Item i on idc.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join ItemParLevel ipl on i.ItemId=ipl.ItemId inner join Unit U on iu.PkUnit=U.UId where im.Date between @From and @To and  ipl.BRId=0 and ipl.SId>0 group by s.Store,c.Category,sc.Subcategory,i.Item,i.ItemId,U.Unit, iu.PkFactor,idc.unit ,ipl.ParLevel,s.SId ,idc.Qty order by isnull(sum(idc.Qty),0) desc